const r = v => v == null ? "" : Math.round(v);

/** type a figure straight into the Efficiency table — saved as a correction on that run */
function editCell(td) {
  if (td.querySelector("input")) return; const row = S._effBy?.[td.dataset.shift]; if (!row) return; const k = td.dataset.ed; const cur = row.ov?.[k] ?? row.eod?.[k] ?? "";
  const prev = td.innerHTML; td.innerHTML = `<input type="number" step="any" inputmode="decimal" value="${cur}" aria-label="${k}">`; const inp = td.firstChild; inp.focus(); inp.select(); let done = false;
  const finish = async save => { if (done) return; done = true; if (!save) { td.innerHTML = prev; return; } const v = inp.value === "" ? null : +inp.value; if (String(v ?? "") === String(cur)) { td.innerHTML = prev; return; }
    td.innerHTML = `<span class="meta">saving…</span>`; const { error } = await sb.from("eff_overrides").upsert({ shift_id: row.x.shift.id, [k]: v, updated_at: new Date().toISOString() }); if (error) { toast(error.message, "err"); td.innerHTML = prev; return; } toast(v == null ? "Back to the driver's figure" : "Saved as a correction", "ok"); await loadAll(); render(); };
  inp.addEventListener("keydown", e => { if (e.key === "Enter") { e.preventDefault(); finish(true); } if (e.key === "Escape") finish(false); if (e.key === "Tab") { e.preventDefault(); const cells = $$("td.ed"); const i = cells.indexOf(td); finish(true).then(() => { const nx = $$("td.ed")[i + (e.shiftKey ? -1 : 1)]; if (nx) editCell(nx); }); } });
  inp.addEventListener("blur", () => finish(true));
}
